#include "postquantiquecoin/wallet/WalletCommands.h"
#include <iostream>
namespace pqc { static Wallet* Ensure(WalletManager& wm,const std::string& n){ auto*w=wm.GetWallet(n); if(!w){ if(wm.OpenWallet(n).IsOk()) w=wm.GetWallet(n); } return w; } int WalletCommands::commandCreate(WalletManager& wm,const std::string& n,const std::string& p){ auto r=wm.CreateWallet(n,p); std::cout<<(r.IsOk()?"wallet created":"error: "+r.Error())<<'\n'; return r.IsOk()?0:1; } int WalletCommands::commandUnlock(WalletManager& wm,const std::string& n,const std::string& p){ auto*w=Ensure(wm,n); if(!w) return 1; auto r=w->Unlock(p); std::cout<<(r.IsOk()?"wallet unlocked":"error: "+r.Error())<<'\n'; return r.IsOk()?0:1; } int WalletCommands::commandLock(WalletManager& wm,const std::string& n){ auto*w=Ensure(wm,n); if(!w) return 1; w->Lock(); std::cout<<"wallet locked\n"; return 0; } int WalletCommands::commandNewAddress(WalletManager& wm,const std::string& n,const std::string& l){ auto*w=Ensure(wm,n); if(!w) return 1; auto r=w->GenerateNewAddress(l); if(r.IsOk()){ w->Save(); std::cout<<r.Value()<<'\n'; return 0; } std::cout<<"error: "<<r.Error()<<'\n'; return 1; } int WalletCommands::commandListAddresses(WalletManager& wm,const std::string& n){ auto*w=Ensure(wm,n); if(!w) return 1; for(const auto&a:w->ListAddresses()) std::cout<<a<<'\n'; return 0; } int WalletCommands::commandBalance(WalletManager& wm,const std::string& n,Blockchain& bc){ auto*w=Ensure(wm,n); if(!w) return 1; std::cout<<w->GetBalance(bc)<<" atoms\n"; return 0; } int WalletCommands::commandSend(WalletManager& wm,const std::string& n,const std::string& to,uint64_t a,uint64_t f,Blockchain& bc){ auto*w=Ensure(wm,n); if(!w) return 1; auto tx=w->CreateTransaction(to,a,f,bc); if(tx.IsErr()){ std::cout<<"error: "<<tx.Error()<<'\n'; return 1; } auto r=bc.AddTransactionToMempool(tx.Value()); std::cout<<(r.IsOk()?"transaction queued":"error: "+r.Error())<<'\n'; return r.IsOk()?0:1; } int WalletCommands::commandBackup(WalletManager& wm,const std::string& n,const std::filesystem::path& p){ auto*w=Ensure(wm,n); if(!w) return 1; auto r=w->Backup(p); std::cout<<(r.IsOk()?"wallet backed up":"error: "+r.Error())<<'\n'; return r.IsOk()?0:1; } int WalletCommands::commandRescan(WalletManager& wm,const std::string& n,Blockchain& bc){ auto*w=Ensure(wm,n); if(!w) return 1; auto r=w->Rescan(bc); return r.IsOk()?0:1; } }
